-- Additive metadata only; immutable bytes live outside the database.
CREATE TABLE IF NOT EXISTS graybox.attachments(id uuid PRIMARY KEY,entity_type text NOT NULL CHECK(entity_type IN ('project','idea','experiment')),entity_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('image','video','demo','repository','demo_link')),name text NOT NULL,caption text NOT NULL,mime_type text NOT NULL,byte_size bigint NOT NULL CHECK(byte_size>=0),sha256 text,url text,uploader_id uuid NOT NULL REFERENCES graybox.users,created_at timestamptz NOT NULL DEFAULT now(),target_revision integer NOT NULL,CHECK((sha256 IS NULL AND url IS NOT NULL AND byte_size=0 AND kind IN ('repository','demo_link')) OR (sha256 ~ '^[a-f0-9]{64}$' AND url IS NULL AND byte_size>0 AND kind IN ('image','video','demo'))));
CREATE TABLE IF NOT EXISTS graybox.attachment_receipts(credential_id uuid NOT NULL REFERENCES graybox.credentials,key uuid NOT NULL,payload_hash text NOT NULL,attachment_id uuid NOT NULL REFERENCES graybox.attachments,PRIMARY KEY(credential_id,key));
CREATE INDEX IF NOT EXISTS attachments_target ON graybox.attachments(entity_type,entity_id,created_at,id);
GRANT SELECT,INSERT ON graybox.attachments,graybox.attachment_receipts TO graybox_runtime;
